// Fire Flow - a river of fire: glowing streams winding around dark, slowly
// turning embers. Parametric (u,v), animated. Seam-free on any closed surface.
//
// HOW IT CLOSES: as in "Torus Flow", the pattern is computed on the flat
// torus of 4D space (cos 2pi u, sin 2pi u, cos 2pi v, sin 2pi v): going once
// around u or v brings the point back where it started, so there is nothing
// to join. Twisted gluing (Klein bottle, Moebius band): set MIRROR_V to 1.0.
// The flow is a domain-warped sum of sines (the "cyclic noise" family),
// written from scratch. The fire is a black-body ramp: red rises first, then
// green, and blue only at white heat.
// Dock colors: u_col1 = tint of the flames (white = natural fire),
//              u_col2 = the embers (darkest tone).

const float SCALE    = 1.0;    // pattern size (bigger = finer)         [0.5 .. 3]
const float ASPECT_V = 1.0;    // density along v relative to u         [0.3 .. 2]
const int   OCTAVES  = 8;      // detail                                [4 .. 9]
const float WARP     = 0.35;   // self-distortion per octave            [0 .. 0.6]
const float GAIN     = 0.68;   // weight of the finer octaves           [0.5 .. 0.8]
const float SPEED    = 0.45;   // flow speed (0 = still)
const float DRIFT    = 0.01;   // slow slide along u (turns per second)
const float HEAT     = 0.9;    // >1 more dark embers, <1 more flame    [0.5 .. 2]
const float MIRROR_U = 0.0;    // 1 = fold u
const float MIRROR_V = 0.0;    // 1 = fold v (Klein bottle, Moebius band)

vec2 seamFold(vec2 q) {
    vec2 tri = 0.5 - abs(fract(q) - 0.5);
    return mix(q, tri, vec2(MIRROR_U, MIRROR_V));
}

vec4 torusPoint(vec2 uv) {
    vec2 a = TAU * uv;
    return SCALE * vec4(cos(a.x), sin(a.x), ASPECT_V * cos(a.y), ASPECT_V * sin(a.y));
}

// fixed 4D turn between octaves: four plane rotations mix all the axes
vec4 turn4(vec4 p) {
    p.xz = mat2(0.80, 0.60, -0.60, 0.80) * p.xz;
    p.yw = mat2(0.28, 0.96, -0.96, 0.28) * p.yw;
    p.xy = mat2(0.96, -0.28, 0.28, 0.96) * p.xy;
    p.zw = mat2(0.60, -0.80, 0.80, 0.60) * p.zw;
    return p;
}

float sineFlow(vec4 p, float time) {
    float acc = 0.0;
    float amp = 1.0;
    float norm = 0.0;
    float freq = 1.7;
    for (int i = 0; i < OCTAVES; i++) {
        p += WARP * sin(p.wxyz * freq + time * (0.6 + 0.21 * float(i)));
        acc += amp * abs(dot(cos(p), sin(p.zwxy)));
        norm += amp;
        amp *= GAIN;
        freq *= 1.31;
        p = 1.47 * turn4(p);
    }
    return acc / norm;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = seamFold(fragCoord / iResolution.xy);
    uv.x += iTime * DRIFT;

    float f = sineFlow(torusPoint(uv), iTime * SPEED);
    // low flow values are the hot streams, high values the embers
    float k = 1.0 - clamp((f - 0.47) / 0.8, 0.0, 1.0);
    k = pow(k, HEAT);

    vec3 ramp = vec3(smoothstep(0.0, 0.45, k),
                     pow(smoothstep(0.25, 0.8, k), 1.1) * 0.95,
                     smoothstep(0.6, 1.0, k) * 0.85);
    vec3 col = u_col2 + (vec3(1.0) - u_col2) * ramp * u_col1;

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
